package com.rpsbattle.worker.remote;
import com.rpsbattle.tournament.domain.*;
import com.rpsbattle.tournament.registry.TournamentRegistry;
import com.rpsbattle.tournament.coding.SubmissionStore;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import static org.assertj.core.api.Assertions.*;

class WorkerOperationsTest extends WorkerPoolTest {
 @Autowired WorkerOperationsService operations;@Autowired WorkerControlService controls;@Autowired TournamentRegistry registry;@Autowired SubmissionStore submissions;
 @Test void operationsProjectionMatchesCanonicalCapacityAndFiltersBeforePaging()throws Exception{try(var admin=new Browser()){UUID actor=admin.account(true);Machine a=machine(actor,Set.of("PYTHON"),4,"TRUSTED"),b=machine(actor,Set.of("JAVA"),2,"COMMUNITY");db.update("update workers set name='Ops Alpha' where id=?",a.id());db.update("update workers set name='Ops Beta' where id=?",b.id());var data=operations.workers(0,25,"Ops Alpha","","","slots");assertThat(data.total()).isEqualTo(1);assertThat(data.items().getFirst().worker()).isEqualTo(telemetry.view(a.id()));assertThat(operations.workers(0,25,"%_' or 1=1","","","name").items()).isEmpty();assertThat(operations.workers(0,25,"Ops","","COMMUNITY","name").items()).allMatch(r->r.worker().trustLevel().equals("COMMUNITY"));assertThatThrownBy(()->operations.workers(0,24,"","","","name")).hasMessage("INVALID_FILTER");assertThatThrownBy(()->operations.workers(0,25,"","HACK","","name")).hasMessage("INVALID_FILTER");}}
 @Test void capacityExcludesDisabledOfflineWrongTrustAndMissingRuntime()throws Exception{try(var admin=new Browser()){UUID actor=admin.account(true);Machine good=machine(actor,Set.of("PYTHON","JAVA","CPP"),4,"TRUSTED"),disabled=machine(actor,Set.of("PYTHON","JAVA","CPP"),3,"TRUSTED"),offline=machine(actor,Set.of("PYTHON","JAVA","CPP"),2,"TRUSTED"),community=machine(actor,Set.of("PYTHON","JAVA","CPP"),2,"COMMUNITY"),incompatible=machine(actor,Set.of("PYTHON"),2,"TRUSTED");db.update("update workers set last_heartbeat_at=? where id not in (?,?,?,?,?)",java.sql.Timestamp.from(Instant.now().minusSeconds(40)),good.id(),disabled.id(),offline.id(),community.id(),incompatible.id());controls.control(disabled.id(),actor,new WorkerControlService.Command(1,"DISABLE","Disabled fixture"));db.update("update workers set last_heartbeat_at=? where id=?",java.sql.Timestamp.from(Instant.now().minusSeconds(40)),offline.id());var spec=spec(actor,"PYTHON","JAVA","TRUSTED");var t=new Tournament(spec.tournamentId().toString(),"Ops capacity",TournamentFormat.ROUND_ROBIN,Instant.now());t.ownerUserId=actor;registry.register(t);submissions.enable(t.id);
  @SuppressWarnings("unchecked") var capacity=(Map<String,Object>)operations.capacity(spec.tournamentId(),"TRUSTED",8);assertThat(capacity).containsEntry("freeSlots",4).containsEntry("compatibleWorkers",1).containsEntry("shortfall",4);controls.control(good.id(),actor,new WorkerControlService.Command(1,"DISABLE","Maintenance"));@SuppressWarnings("unchecked") var stopped=(Map<String,Object>)operations.capacity(spec.tournamentId(),"TRUSTED",8);assertThat(stopped).containsEntry("freeSlots",0);}}
 @Test void operationsEndpointsRequireAdminAndNeverExposeWorkerCredentials()throws Exception{try(var admin=new Browser();var user=new Browser()){UUID actor=admin.account(true);user.account(false);var m=machine(actor,Set.of("PYTHON"),1,"TRUSTED");for(String path:List.of("/api/admin/workers/operations","/api/admin/workers/operations/"+m.id(),"/api/admin/worker-assignments/tournaments")){assertThat(user.call(path,"GET",null,null,false).status()).isEqualTo(403);var response=admin.call(path,"GET",null,null,false);assertThat(response.status()).isEqualTo(200);assertThat(response.body().toString()).doesNotContain(m.enrolled().workerCredential(),"credential_hash","token_hash","spec_json","sourceCode");}}}
 @Test void tokenMetadataTracksNewUsageWithoutRevealingSecret()throws Exception{try(var admin=new Browser()){UUID actor=admin.account(true);var token=identities.issue(actor,1,15);var worker=identities.register(registration(token.registrationToken()));var metadata=identities.tokens().stream().filter(t->t.id().equals(token.id())).findFirst().orElseThrow();assertThat(metadata.status()).isEqualTo("USED");assertThat(metadata.createdAt()).isNotNull();assertThat(metadata.lastUsed()).isNotNull();assertThat(metadata.usedBy()).anyMatch(w->w.get("id").equals(worker.worker().workerId()));assertThat(metadata.toString()).doesNotContain(token.registrationToken(),worker.workerCredential());}}
}
